+        info: &mut uapi::drm_nova_info,
+        _file: &drm::File<File>,
+    ) -> Result<u32> {
+        if info.data == 0 {
+            info.size = match info.id {
+                uapi::DRM_NOVA_INFO_GPU => size_of::<GpuInfo>() as u32,
+                _ => return Err(EINVAL),
+            };
+            return Ok(0);
